// Title: Inject custom CSS styling for path elements into an SVG worksheet exported with Aspose.Cells for .NET
// Common Searches: C# add a <style> element to SVG generated by Aspose.Cells | change stroke and fill of path elements in Aspose.Cells SVG output | apply CSS to all paths after saving workbook as SVG with Aspose.Cells | use XDocument to style Aspose.Cells exported SVG programmatically | customize line color and width in SVG worksheet created by Aspose.Cells
// Tags: inject CSS into Aspose.Cells SVG export | modify SVG path attributes with XDocument in C# | custom stroke width for Aspose.Cells generated SVG | embed CSS block in Aspose.Cells SVG file | Aspose.Cells SaveFormat.Svg styling example

using System;
using System.IO;
using System.Xml.Linq;
using Aspose.Cells;

// The example creates a workbook, saves it as an SVG file using Aspose.Cells, loads the SVG with XDocument, inserts a <style> element that defines CSS rules for all <path> elements (red stroke, 2 px width, no fill), optionally updates each path's style attribute, and saves the modified SVG back to disk.
class SvgStylingExample
{
    static void Main()
    {
        // Create a new workbook and add some data (replace with load if needed)
        Workbook workbook = new Workbook();
        Worksheet sheet = workbook.Worksheets[0];
        sheet.Cells["A1"].PutValue("Sample");
        sheet.Cells["B2"].PutValue(123);

        // Export the worksheet to SVG
        string svgFilePath = "worksheet.svg";
        workbook.Save(svgFilePath, SaveFormat.Svg);

        // Load the generated SVG document
        XDocument svgDoc = XDocument.Load(svgFilePath);

        // Ensure the SVG namespace is defined for queries
        XNamespace ns = "http://www.w3.org/2000/svg";

        // Add a <style> element to define CSS for all <path> elements
        XElement styleElement = new XElement(ns + "style",
            new XAttribute("type", "text/css"),
            // Example CSS: red stroke, 2px width, no fill
            "path { stroke: red; stroke-width: 2; fill: none; }"
        );

        // Insert the <style> element as the first child of the root <svg> element
        XElement rootSvg = svgDoc.Root;
        rootSvg.AddFirst(styleElement);

        // OPTIONAL: If you prefer to modify each <path> directly, uncomment the following block
        /*
        foreach (XElement path in rootSvg.Descendants(ns + "path"))
        {
            // Append or replace the style attribute
            string existingStyle = (string)path.Attribute("style") ?? "";
            string newStyle = "stroke: red; stroke-width: 2; fill: none;";
            path.SetAttributeValue("style", existingStyle + (existingStyle.Length > 0 ? " " : "") + newStyle);
        }
        */

        // Save the modified SVG back to file
        svgDoc.Save(svgFilePath);

        Console.WriteLine("SVG exported and styled successfully.");
    }
}
